struct Vector {
    int sz;       // 요소의 개수
    double* elem; // 요소를 가리키는 포인터
};

void vector_init(Vector& v, int s)
{
    v.elem = new double[s]; // s개의 double로 이뤄진 배열 할당
    v.sz = s;
}

class Vector {
public:
    Vector(int s) :elem{new double[s]}, sz{s} { } // Vector 생성
    double& operator[](int i) { return elem[i]; } // 요소 접근: 첨자 연산
    int size() { return sz; }
private:
    double* elem; // 요소를 가리키는 포인터
    int sz;       // 요소의 개수
};

